insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('wem-mit-da-geam-neema', 'wem mit da Geam neema', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden mit der Germ nehmen', '[{"kategorie": "wörtlich", "text": "\"jemanden mit viel Schmäh, Charme oder List um den Finger wickeln\""}, {"kategorie": "", "text": "jemanden mit viel Schmäh rumkriegen\""}, {"kategorie": "", "text": "jemanden durch sanftes Taktieren auf seine Seite ziehen"}]'::jsonb, 'Dea hods mit da Geam gnumma - a bissl Scharm, a bissl Schmää, und si woa hii und weg!'),
  ('dea-hods-mit-da-geam-gnumma-a-bissl-scharm-a-bissl-schmaeae-und-si-woa-hii-und-weg', 'Dea hods mit da Geam gnumma - a bissl Scharm, a bissl Schmää, und si woa hii und weg!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der hat sie mit der Germ genommen – ein bisschen Charme, ein bisschen Schmäh, und sie war hin und weg!', '[{"kategorie": "wörtlich", "text": "\"Der hat sie mit Charme und Schmäh um den Finger gewickelt – und sie war hin und weg!\"  2. Der hat sie mit dem vollen Programm eingeseift – ein bisschen Charme, ein bisschen Schmäh, und sie war ihm schon erlegen!  3. Der hat sie mit seinem Schmäh weichgekocht – und sie ist drauf reingefallen wie nix!"}]'::jsonb, 'wem mit da Geam neema'),
  ('in-da-geam-sei', 'in da Geam sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'in der Germ sein', '[{"kategorie": "wörtlich", "text": "\"in der Hefe sein\""}, {"kategorie": "fig.", "text": "in der Patsche sitzen"}, {"kategorie": "", "text": "in der Klemme stecken"}, {"kategorie": "", "text": "[[in]] Scheabm aufhaum"}]'::jsonb, 'Seita de Hockn valuan hod, isa sauwa in da Geam!'),
  ('seita-de-hockn-valuan-hod-isa-sauwa-in-da-geam', 'Seita de Hockn valuan hod, isa sauwa in da Geam!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seit er die Hacke verloren hat, ist er sauber in der Germ!', '[{"kategorie": "wörtlich", "text": "\"Seit er seinen Job verloren hat, steckt er tief in der Patsche!\"  2. Seitdem er die Arbeit verloren hat, ist er in einer in einer richtig prekären Lage!  3. Nach seinem Jobverlust sitzt er ordentlich in der Klemme!"}]'::jsonb, 'in da Geam sei'),
  ('red-ned-so-gschead-dahea', 'Red ned so gschead dahea!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Red nicht so geschert daher!', '[{"kategorie": "wörtlich", "text": "\"Red nicht so proletenhaft daher!\"  2. Sprich nicht so derb!  3. A bisserl weniger Gsindl-Ton, bitte schön!"}]'::jsonb, ''),
  ('a-gscheada-haummae', 'a gscheada Haummä', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'ein gescherter Hammel', '[{"kategorie": "wörtlich", "text": "\"ein geschorener Hammel\" (im Mittelalter und der frühen Neuzeit war die Haartracht ein wichtiges äußeres Zeichen sozialer Zugehörigkeit. Adelige, Bürger, Geistliche trugen oft längeres oder kunstvoll frisiertes Haar (manchmal Perücken). Unfreie, Bauern, Knechte, untere Stände hingegen mussten – teils aus Vorschrift, teils aus gesellschaftlicher Erwartung – kurzes oder geschorenes Haar tragen. Somit wurde das \"Geschoren-Sein\" zum sichtbaren Symbol sozialer Minderstellung)"}, {"kategorie": "fig.", "text": "\"ein ungehobelter Mensch\", \"eine unzivilisierte Person\", \"ein Mensch ohne Manieren\", \"ein Mensch ohne Anstand\""}]'::jsonb, 'Des is a gscheada Haummä - dea putzd si de Goschn imma min Äamä oo!'),
  ('des-is-a-gscheada-haummae-dea-putzd-si-de-goschn-imma-min-aeamae-oo', 'Des is a gscheada Haummä - dea putzd si de Goschn imma min Äamä oo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein gescherter Hammel - der putzt sich die Goschen immer mit''m Ärmel ab!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein ungehobelter Kerl – der wischt sich den Mund immer mit dem Ärmel ab!\"  2. Das ist ein Mensch ohne Anstand – der putzt sich den Mund immer mit dem Ärmel statt mit der Serviette ab!  3. Das ist ein Mensch ohne Tischmanieren - der Prolet schmiert sich die Essensreste in den Ärmel!"}]'::jsonb, 'a gscheada Haummä'),
  ('heast-gscheada-nimm-de-haend-aus-da-hoosn-waunnst-mit-mia-reedst', 'Heast, Gscheada, nimm de Händ aus da Hoosn, waunnst mit mia reedst!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör mal, du G''scherter, nimm gefälligst die Hände aus der Hose, wenn du mit mir redest!', '[{"kategorie": "wörtlich", "text": "\"Hör mal, du Bauerntölpel, nimm gefälligst die Hände aus der Hose, wenn du mit mir redest!\"  2. Hör mal, du Hinterwäldler, nimm gefälligst die Hände aus den Taschen, wenn du mit mir sprichst!  3. Hey, du Provinzler, nimm sofort die Griffel aus der Hose, wenn du mit mir sprichst!"}]'::jsonb, ''),
  ('waunn-de-griassnockaln-gschmoizn-san-schmeckns-glei-vueue-bessa', 'Waunn de Griassnockaln gschmoizn san, schmeckns glei vüü bessa!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn die Grießnockerln geschmalzt sind, schmecken sie gleich viel besser!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Grießnockerln mit Schmalz zubereitet sind, schmecken sie gleich viel besser!\"  2. Mit etwas Schmalz verfeinert, schmecken die Grießnockerln noch viel besser!  3. Angeschmalzt schmecken die Grießnockerln gleich viel kräftiger!"}]'::jsonb, ''),
  ('waassd-wos-de-fiara-bia-valaungan-gschmoizn-is-goa-ka-ausdruck', 'Waassd, wos de fiara Bia valaungan? Gschmoizn is goa ka Ausdruck!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Weißt du, was die für ein Bier verlangen? Geschmalzen ist gar kein Ausdruck!', '[{"kategorie": "wörtlich", "text": "\"Weißt du, was die für ein Bier verlangen? Das ist schlichtweg überzogen!\"  2. Der Bierpreis ist echt gesalzen – und das ist noch höflich formuliert!  3. Für ein Bier verlangen die einen Preis, der gepfeffert ist!"}]'::jsonb, ''),
  ('gschmoizane-preis', 'gschmoizane Preis', '', '', '', 'Wiener Sprüche, die sitzen!', 'geschmalzene Preise', '[{"kategorie": "wörtlich", "text": "\"saftige Preise\""}, {"kategorie": "", "text": "\"überteuerte Preise\""}, {"kategorie": "", "text": "\"gesalzene Preise\""}, {"kategorie": "", "text": "\"gepfefferte Preise\""}]'::jsonb, 'Na servas, des san owa gschmoizane Preis fiaran Lunganbroodn – hobds des Rindsviich leichd mit Goid gfiadad?'),
  ('na-servas-des-san-owa-gschmoizane-preis-fiaran-lunganbroodn-hobds-des-rindsviich-leichd-mit-goid-gfiadad', 'Na servas, des san owa gschmoizane Preis fiaran Lunganbroodn – hobds des Rindsviich leichd mit Goid gfiadad?', '', '', '', 'Wiener Fleischhauer-Slang', 'Du meine Güte, das sind heute aber geschmalzene Preise für einen Rindslungenbraten – habt ihr das Rind etwa mit Gold gefüttert?', '[{"kategorie": "wörtlich", "text": "\"Du meine Güte, das sind heute aber gesalzene Preise für ein Rinderfilet – habt ihr das Rind etwa mit Gold gefüttert?\"  2. Heiliger Bimbam - bei den Preisen für ein Rinderfilet könnte man meinen, das Rind hat Diamanten gefressen!  3. Also ehrlich, bei diesen Preisen für ein Rindefilet glaubt man fast, ihr habt das Tier mit Trüffeln und Goldstaub aufgezogen!"}]'::jsonb, ''),
  ('a-gschmoizane-schdroof', 'a gschmoizane Schdroof', '', '', '', 'Wiener Gaunersprache', 'eine geschmalzene Strafe', '[{"kategorie": "wörtlich", "text": "\"eine fette Strafe\""}, {"kategorie": "", "text": "\"eine saftige Strafe\""}, {"kategorie": "", "text": "\"eine gepfefferte Strafe\""}, {"kategorie": "", "text": "\"eine empfindliche Strafe\""}]'::jsonb, 'Weng dea klaan Linkn glei so a gschmoizane Schdroof - da Kaadi muass augschitt sei!'),
  ('weng-dea-klaan-linkn-glei-so-a-gschmoizane-schdroof-da-kaadi-muass-augschitt-sei', 'Weng dea klaan Linkn glei so a gschmoizane Schdroof - da Kaadi muass augschitt sei!', '', '', '', 'Wiener Gaunersprache', 'Wegen dieser kleinen Linken gleich so eine geschmalzene Strafe - der Kadi muss angeschüttet sein!', '[{"kategorie": "wörtlich", "text": "\"Wegen dieser kleinen Gaunerei gleich so eine gesalzene Strafe - der Richter muss verrückt sein!\"  2. Wegen so einem Bagatelldelikt gleich so eine saftige Strafe – der Richter muss den Verstand verloren haben!  3. Wegen dieser Lappalie gleich so eine gepfefferte Strafe - der Richter tickt ja wohl nicht mehr richtig!"}]'::jsonb, 'a gschmoizane Schdroof'),
  ('a-gschnetzlds-ghead-peafekd-oogschmeckd-ned-zu-soizig-ned-zu-faad', 'A Gschnetzlds ghead peafekd oogschmeckd - ned zu soizig, ned zu faad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Geschnetzeltes gehört perfekt abgeschmeckt – nicht zu salzig, nicht zu fad!', '[{"kategorie": "wörtlich", "text": "\"Ein Geschnetzeltes muss geschmacklich gut abgestimmt sein – weder zu salzig noch zu mild!\"  2. Ein Geschnetzeltes entfaltet seinen vollen Geschmack nur, wenn es richtig gewürzt ist – nicht zu viel, nicht zu wenig!  3. Ein gut zubereitetes Geschnetzeltes lebt von der perfekten Balance zwischen Salz und Würze!"}]'::jsonb, ''),
  ('wiara-schdingads-gsoeoechds-umanaundaliing', 'wiara schdingads Gsööchds umanaundaliing', '', '', '', 'Wiener Sprüche, die sitzen!', 'wie ein stinkendes Geselchtes herumliegen', '[{"kategorie": "wörtlich", "text": "\"herumlliegen wie ein stinkendes Selchfleisch\""}, {"kategorie": "", "text": "herumlungern wie ein stinkendes Faultier"}, {"kategorie": "", "text": "wie totes Fleisch in der Gegend herumliegen"}]'::jsonb, ''),
  ('aum-suundog-liigda-wiara-schdingads-gsoeoechds-auf-da-couch-und-bewegd-si-kan-millimeeta', 'Aum Suundog liigda wiara schdingads Gsööchds auf da Couch und bewegd si kan Millimeeta!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Am Sonntag liegt er wie ein stinkendes Geselchtes auf der Couch und bewegt sich keinen Millimeter!', '[{"kategorie": "wörtlich", "text": "\"Am Sonntag liegt er wie ein stinkendes Selchfleisch auf der Couch und bewegt sich keinen Millimeter!\"  2. Am Sonntag liegt er wie ein stinkendes Faultier auf der Couch und bewegt sich keinen Millimeter!  3. Am Sonntag liegt er wie totes Fleisch auf der Couch und bewegt sich keinen Millimeter!"}]'::jsonb, 'wiara schdingads Gsööchds umanaundaliing'),
  ('dea-hod-de-yoga-schdund-afoch-gschbritzd', 'Dea hod de Yoga-Schdund afoch gschbritzd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat die Yoga-Stunde einfach gespritzt!', '[{"kategorie": "wörtlich", "text": "\"Der hat die Yoga-Stunde einfach sausen lassen!\"  2. Der hat die Yoga-Stunde einfach geschwänzt!  3. Der hat die Yoga-Stunde einfach geschmissen!"}]'::jsonb, ''),
  ('dea-is-voi-gschbritzd-und-gegn-hian-gimpfd', 'Dea is voi gschbritzd und gegn Hian gimpfd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der ist voll gespritzt und gegen Hirn geimpft!', '[{"kategorie": "wörtlich", "text": "\"Der ist total plemplem und gegen Hirn geimpft!\"  2. Dieser Trottel ist gegen Verstand geimpft und für immer hirnimmun!  3. Der Typ ist vollkommen behämmert und gegen jedwede Intelligenz immun!"}]'::jsonb, ''),
  ('de-soch-is-gschbritzd', 'De Soch is gschbritzd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Die Sache ist gespritzt!', '[{"kategorie": "wörtlich", "text": "\"Die Sache ist erledigt!\"  2. Die Sache ist unter Dach und Fach!  3. Die Sache ist vom Tisch"}]'::jsonb, ''),
  ('gott-vataeud-hian-owa-de-gschbritzdn-schdengan-min-reengschiam-do', 'Gott vatäud Hian - owa de Gschbritzdn schdengan min Reengschiam do!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Gott verteilt Hirn - aber die G''spritzten stehen mit dem Regenschirm da!', '[{"kategorie": "wörtlich", "text": "\"Gott verteilt Hirn - aber die Minderbemittelten stehen mit dem Regenschirm da!\"  2. Es hat Hirn geregnet - aber die Hirnlosen haben sich unter dem Regenschirm versteckt!  3. Der Schöpfer ließ Verstand vom Himmel fallen – doch der Einfältige duckte sich höflich!"}]'::jsonb, ''),
  ('a-mokka-gschbritzd', 'A Mokka, gschbritzd!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ein Mokka, gespritzt!', '[{"kategorie": "wörtlich", "text": "\"Einen Mokka, aber einen gespritzten!\"  2. \"Ein Espresso mit einem Spritzer Rum!\"  3. \"Ein Mokka, gespritzt mit Weinbrand!\""}]'::jsonb, ''),
  ('dea-is-so-gschdopfd-dass-eam-de-weiwa-haufnweis-zuafliang', 'Dea is so gschdopfd, dass eam de Weiwa haufnweis zuafliang!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der ist so gestopft, dass ihm die Weiber haufenweise zufliegen!', '[{"kategorie": "wörtlich", "text": "\"Der ist so wohlhabend, dass ihm das weibliche Geschlecht haufenweise zufliegt!\"  2. Er ist so vermögend, dass er bei Frauen enormen Zulauf hat!  3. Der hat so viel Kohle, dass ihm die Weiber wie Motten zufliegen!"}]'::jsonb, ''),
  ('gschdopfd-voi', 'gschdopfd voi', '', '', '', 'Wiener Sprüche, die sitzen!', 'gestopft voll', '[{"kategorie": "wörtlich", "text": "\"prallvoll\" (vom mittelhochdeutschen \"stoffen\"=\"stopfen\")"}, {"kategorie": "allg.", "text": "gerappelt voll, gesteckt voll, zum Bersten voll, randvoll, überfüllt, [[bummvoi]], [[grammäd]] voi, [[gschoodad]] voi, [[gschdrotzd]] voi"}]'::jsonb, 'De Hittn woa gschdopfd voi - do host ned amoi mea umkippn kenna!'),
  ('de-hittn-woa-gschdopfd-voi-do-host-ned-amoi-mea-umkippn-kenna', 'De Hittn woa gschdopfd voi - do host ned amoi mea umkippn kenna!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Hütte war gestopft voll - da hast du nicht einmal mehr umkippen können!', '[{"kategorie": "wörtlich", "text": "\"Das Lokal war gesteckt voll - da hast du nicht mal mehr umkippen können!\"  2. Das Beisl war zum Bersten voll - wer umkippte, ist einfach senkrecht weitergelegen!  3. Die Hütte war so voll - da hattest du nicht mal Platz zum Atmen, geschweige denn zum Umfallen!"}]'::jsonb, 'gschdopfd voi'),
  ('gschdrotzd-voi', 'gschdrotzd voi', '', '', '', 'Wiener Sprüche, die sitzen!', 'gestrotzt voll', '[{"kategorie": "wörtlich", "text": "\"prallvoll\" (vom mittelhochdeutschen \"stroʒʒen \"=\"angeschwollen sein\")"}, {"kategorie": "allg.", "text": "gerappelt voll, gesteckt voll, zum Bersten voll, randvoll, überfüllt, [[bummvoi]], [[grammäd]] voi, [[gschoodad]] voi, [[gschdrotzd]] voi, [[gschdopfd]] voi"}]'::jsonb, 'De Hittn woa gschdrotzd voi - do host ned amoi mea umkippn kenna!'),
  ('de-hittn-woa-gschdrotzd-voi-do-host-ned-amoi-mea-umkippn-kenna', 'De Hittn woa gschdrotzd voi - do host ned amoi mea umkippn kenna!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Hütte war gestrotzt voll - da hast du nicht einmal mehr umkippen können!', '[{"kategorie": "wörtlich", "text": "\"Das Lokal war gesteckt voll - da hast du nicht mal mehr umkippen können!\"  2. Das Beisl war zum Bersten voll - wer umkippte, ist einfach senkrecht weitergelegen!  3. Die Hütte war so voll - da hattest du nicht mal Platz zum Atmen, geschweige denn zum Umfallen!"}]'::jsonb, 'gschdrotzd voi'),
  ('de-gschdopfdn-kennan-sis-imma-richtn', 'De Gschdopfdn kennan sis imma richtn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Gestopften können es sich imme richten!', '[{"kategorie": "wörtlich", "text": "\"Die Reichen können es sich immer richten!\"  2. Die mit den vollen Taschen kommen immer irgendwie durch!  3. Die Großverdiener können es sich immer zurechtbiegen!"}]'::jsonb, ''),
  ('dea-saufd-wiara-loch-is-owa-gsund-wiara-fisch-im-wossa', 'Dea saufd wiara Loch - is owa gsund wiara Fisch im Wossa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der sauft wie ein Loch - ist aber gesund wie ein Fisch im Wasser!', '[{"kategorie": "wörtlich", "text": "\"Der säuft wie ein Fass ohne Boden – und trotzdem ist er kerngesund!\"  2. Der schüttet sich literweise Alkohol rein – und rennt trotzdem kerngesund herum wie ein Reh!  3. Der hat mehr Promille als ein Weinkeller - und und trotzdem is er pumperlg’sund wie eine Bachforelle!"}]'::jsonb, ''),
  ('i-bin-gsund-ausse-aus-da-numma-kaa-krotza-kaa-aunzeig', 'I bin gsund ausse aus da Numma - kaa Krotza, kaa Aunzeig!', '', '', '', 'Wiener Gaunersprache', 'Ich bin gesund raus aus der Nummer - kein Kratzer, keine Anzeige!', '[{"kategorie": "wörtlich", "text": "\"Ich bin heil aus der Sache raus – keine Verletzung, kein juristisches Nachspiel!\"  2. Ich bin ungeschoren davongekommen – keine Anzeige, keine Blessuren!  3. Ich habe die Sache schadlos und ohne Strafe überstanden!"}]'::jsonb, ''),
  ('des-is-owa-gsund-teia', 'Des is owa gsund teia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist aber gesund teuer!', '[{"kategorie": "wörtlich", "text": "\"Das ist aber ordentlich teuer!\"  2. Das ist aber mehr als teuer!  3. Das ist aber echt teuer!"}]'::jsonb, ''),
  ('a-gsunde-waatschn', 'a gsunde Waatschn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine gesunde Watsche', '[{"kategorie": "wörtlich", "text": "\"eine heilsame Ohrfeige\""}, {"kategorie": "", "text": "\"eine pädagogisch wertvolle Ohrfeige\""}, {"kategorie": "", "text": "eine charakterbildende Ohrfeige, [[Flaschen]], [[Fotzen]], [[Tschinelle]]"}]'::jsonb, 'Dem Giftniigl häd a gsunde Waatschn sicha ned gschood!'),
  ('dem-giftniigl-haed-a-gsunde-waatschn-sicha-ned-gschood', 'Dem Giftniigl häd a gsunde Waatschn sicha ned gschood!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dem Giftnigel hätte eine gesunde Watsche sicher nicht geschadet!', '[{"kategorie": "wörtlich", "text": "\"Dem Hitzkopf hätte eine gesunde Watsche sicher nicht geschadet!\"  2. Diesem Wüterisch hätte eine charakterbildende Ohrfeige sicher gut getan!  3. Diesem gehässigen Menschen hätte eine drastische, aber wirksame Zurechtweisung bestimmt nicht geschadet!"}]'::jsonb, ''),
  ('sunst-bist-aeae-gsund', 'Sunst bist ää gsund?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sonst bist du eh gesund?', '[{"kategorie": "wörtlich", "text": "\"Sonst geht es dir aber eh gut?\"  2. Sonst ist bei dir aber eh noch alles in der Reihe?  3. Aber sonst bist du eh noch ganz richtig im Schädel?"}]'::jsonb, ''),
  ('na-seavas-dea-schaud-gsund-aus', 'Na seavas, dea schaud gsund aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na servus, der schaut gesund aus!', '[{"kategorie": "wörtlich", "text": "\"Du meine Güte, der sieht echt erbärmlich aus!\"  2. Heiliger Bimbam, der sieht wirklich übel mitgenommen aus!  3. Mein Gott, der schaut aus wie durch den Wolf gedreht!"}]'::jsonb, ''),
  ('aum-bueffee-is-a-wueuede-wualarei', 'Aum Büffee is a wüüde Wualarei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Am Buffet ist eine wilde Wurlerei!', '[{"kategorie": "wörtlich", "text": "\"Am Buffet herrscht ein wildes Gedränge!\"  2. Am Buffet geht''s zu wie in einem Taubenschlag!  3. Am Buffet ist der Bär los!"}]'::jsonb, ''),
  ('i-blick-duach-des-gwual-nimma-duach', 'I blick duach des Gwual nimma duach!"', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich blicke durch dieses Gewurl nicht mehr durch!', '[{"kategorie": "wörtlich", "text": "\"Ich blicke in diesem Getümmel nicht mehr durch!\"  2. Ich verliere den Überblick in diesem Gedränge!  3. Ich kann mich in diesem Kuddelmuddel nicht mehr zurechtfinden!"}]'::jsonb, ''),
  ('si-ins-gwual-haun', 'si ins Gwual haun', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'sich ins Gewurl hauen', '[{"kategorie": "wörtlich", "text": "\"sich ins Getümmel schmeißen\""}, {"kategorie": "", "text": "sich ins Gewühl stürzen"}, {"kategorie": "", "text": "sich mitten ins Geschehen begeben"}]'::jsonb, 'Moch a Säun, I hau mi ins Gwual und schwimm umd Wäsch!'),
  ('si-ins-gwual-schmeissn', 'si ins Gwual schmeissn', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'sich ins Gewurl schmeißen', '[{"kategorie": "wörtlich", "text": "\"sich ins Getümmel werfen\""}, {"kategorie": "", "text": "sich ins Gewühl stürzen"}, {"kategorie": "", "text": "sich mitten ins Geschehen begeben"}]'::jsonb, ''),
  ('dei-bua-is-a-klaans-gfraassd', 'Dei Bua is a klaans Gfraassd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dein Bub ist ein kleines Gfraßt!', '[{"kategorie": "wörtlich", "text": "\"Dein Bub ist ein kleiner Quälgeist!\"  2. Dein Junge ist ein kleiner Rabauke!  3. Dein Sohn ist ein kleiner Unruhestifter!"}]'::jsonb, ''),
  ('i-hob-glei-gwussd-dass-dea-a-linkes-gfraassd-is', 'I hob glei gwussd, dass dea a linkes Gfraassd is!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ich habe gleich gewusst, dass der ein linkes Gfraßt ist!', '[{"kategorie": "wörtlich", "text": "\"Ich wusste gleich, dass der ein hinterfotziges Miststück ist!\"  2. Mir war sofort klar, dass der eine falsche Ratte ist!  3. Ich hab sofort bemerkt, dass der ein hinterhältiges Schwein ist!"}]'::jsonb, ''),
  ('des-gfraassd-losst-si-ned-eischoitn', 'Des Gfraassd losst si ned eischoitn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieses Gfraßt lässt sich nicht einschalten!', '[{"kategorie": "wörtlich", "text": "\"Dieses bockige Gerät lässt sich nicht einschalten!\"  2. Dieses störrische Gerät will einfach nicht starten!  3. Dieses widerspenstige Gerät lässt sich nicht überlisten!"}]'::jsonb, ''),
  ('oida-des-is-kaa-mensch-des-is-a-gfraassdsackl-vom-diinst', 'Oida, des is kaa Mensch, des is a Gfraassdsackl vom Diinst!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Alter, das ist kein Mensch, das ist ein Gfraßtsackel vom Dienst!', '[{"kategorie": "wörtlich", "text": "\"Alter, das ist kein Mensch, das ist ein berufsmäßiger Widerling!\""}]'::jsonb, ''),
  ('a-so-a-gfraassdsackl', 'A so a Gfraassdsackl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ein so ein Gfraßtsackel!', '[{"kategorie": "wörtlich", "text": "\"Was für ein hinterfotziges Miststück!\" 2. Was für ein linker Hund!  3. Was für ein boshafter Fiesling!  4. (in Bezug auf Kinder): Was für ein nervender, kleiner Quälgeist!"}]'::jsonb, ''),
  ('a-so-a-gfraassd', 'A so a Gfraassd!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Ein so ein Gfraßt!', '[{"kategorie": "wörtlich", "text": "\"Was für ein hinterfotziges Miststück!\" 2. Was für ein linker Hund!  3. (in Bezug auf Kinder): Was für ein nervender, kleiner Quälgeist!"}]'::jsonb, ''),
  ('dea-is-ned-nua-a-hundsgfraassd-dea-is-da-deifae-in-menschngeschdoid', 'Dea is ned nua a Hundsgfraassd - dea is da Deifä in Menschngeschdoid!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Der ist nicht nur ein Hundsgfraßt - der ist der Teufel in Menschengestalt!', '[{"kategorie": "wörtlich", "text": "\"Der ist nicht nur ein hundsgemeines Miststück - der ist der Teufel in Menschengestalt!\"  2. Er ist nicht nur skrupellos – er ist das personifizierte Böse!  3. Der ist nicht nur ein mieses Schwein - der ist der personifizierte Teufel auf zwei Beinen!"}]'::jsonb, ''),
  ('woat-nua-du-saugfraassd-waunn-i-di-aum-krawattl-hob-brennd-da-da-huat', 'Woat nua, du Saugfraassd, waunn I di aum Krawattl hob, brennd da da Huat!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Wart nur, du Saugfraßt, wenn ich dich am Krawattl hab, brennt dir der Hut!', '[{"kategorie": "wörtlich", "text": "\"Warte nur, du Mistkerl – wenn ich dich in die Finger bekomme, dann Gnade dir Gott!\"  2. Warte nur, du mieses Schwein - wenn ich dich zu fassen kriege, dann rappelt’s im Karton!  3. Wart ab, du elendige Bazille - wenn ich dich erwische, geht''s dir an den Kragen!"}]'::jsonb, ''),
  ('hackln-is-und-bleibt-a-gfrett', 'Hackln is und bleibt a Gfrett!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hackeln ist und bleibt ein Gfrett!', '[{"kategorie": "wörtlich", "text": "\"Arbeiten ist und bleibt eine mühsame Sache!\"  2. Arbeiten ist und bleibt eine schlimme Plackerei!  3. Arbeiten ist und bleibt nichts als eine lebenslange Quälerei!"}]'::jsonb, ''),
  ('des-is-a-gfrett', 'Des is a Gfrett!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist ein Gfrett!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Krampf!\"  2. \"Das ist ein Jammer!\"  3. \"Das ist ein Hickhack!\"  4. \"Das ist ein Fiasko!\"  5. \"Das ist ein Trauerspiel!\""}]'::jsonb, ''),
  ('des-is-kaa-gfrett-ned', 'Des is kaa Gfrett ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist kein Gfrett nicht!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Malheur!\"  2. \"Das ist kein Unglück!\"  3. \"Das ist keine Katastrophe!\"  4. \"Das ist kein Weltuntergang!\""}]'::jsonb, ''),
  ('a-gfrett-sei', 'a Gfrett sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein Gfrett sein', '[{"kategorie": "wörtlich", "text": "\"eine mühsame Angelegenheit sein\""}, {"kategorie": "", "text": "\"ein Krampf sein\""}, {"kategorie": "", "text": "\"ein Unglück sein\""}, {"kategorie": "", "text": "\"ein Fiasko sein\""}]'::jsonb, 'Es is a Gfrett, owa I kaunn''s ned ändan!'),
  ('es-is-a-gfrett-owa-i-kaunn-s-ned-aendan', 'Es is a Gfrett, owa I kaunn''s ned ändan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Es ist ein Gfrett, aber ich kann''s nicht ändern!', '[{"kategorie": "wörtlich", "text": "\"Es ist ein Krampf, aber ich kann''s nicht ändern!\"  2. Es ist frustrierend, aber ich kann nichts dagegen tun!  3. Es ist ein Fiasko, aber ich kann''s nicht ändern!  4. Es ist eine belastende Situation, aber das liegt nicht an mir!"}]'::jsonb, 'a Gfrett sei'),
  ('es-is-zaach-owa-es-hueuefd-nix', 'Es is zaach, owa es hüüfd nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Es ist zäh, aber es hilft nichts!', '[{"kategorie": "wörtlich", "text": "\"Es ist mühsam, aber es lässt sich nicht vermeiden!\"  2. Es ist frustrierend, aber Jammern hilft auch nichts!  3. Es ist echt mühsam, aber es muss halt sein!"}]'::jsonb, ''),
  ('mit-wem-a-gfrett-haum', 'mit wem a Gfrett haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'mit jemandem ein Gfrett haben', '[{"kategorie": "wörtlich", "text": "\"ein angespanntes Verhältnis zu jemandem haben\""}, {"kategorie": "", "text": "\"Ärger mit jemandem haben\""}, {"kategorie": "", "text": "\"mit jemandem im Clinch liegen\""}, {"kategorie": "", "text": "\"mit jemandem auf Kriegsfuß stehen\""}]'::jsonb, 'Seita unsa Schääf is, hauma a Gfrett mit eam!'),
  ('seita-unsa-schaeaef-is-hauma-a-gfrett-mit-eam', 'Seita unsa Schääf is, hauma a Gfrett mit eam!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Seit er unser Chef ist, haben wir ein Gfrett mit ihm!', '[{"kategorie": "wörtlich", "text": "\"Seit er unser Chef ist, haben wir nur noch Ärger mit ihm!\"  2. Seit er unser Vorgesetzter ist, ist alles mit ihm nur noch ein einziger Krampf!  3. Seit er das Kommando hat, haben wir mit ihm nur noch Zores!"}]'::jsonb, 'mit wem a Gfrett haum'),
  ('mit-wos-a-gfrett-haum', 'mit wos a Gfrett haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'mit etwas ein Gfrett haben', '[{"kategorie": "wörtlich", "text": "\"Ärger mit etwas haben\""}, {"kategorie": "", "text": "\"ein Problem mit etwas haben\""}, {"kategorie": "", "text": "\"Mühe mit etwas haben\""}]'::jsonb, 'I hob a Gfrett damit, dass hinta mein Ruckn schdändig intrigiad wiad!'),
  ('i-hob-a-gfrett-damit-dass-hinta-mein-ruckn-schdaendig-intrigiad-wiad', 'I hob a Gfrett damit, dass hinta mein Ruckn schdändig intrigiad wiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich habe ein Gfrett damit, dass hinter meinem Rücken ständig intrigiert wird!', '[{"kategorie": "wörtlich", "text": "\"Ich habe ein ernsthaftes Problem damit, dass ständig hinter meinem Rücken intrigiert wird!\"  2. Ich empfinde es als sehr problematisch, dass ständig heimlich gegen mich intrigiert wird!  3. Ich hab echt ein Problem damit, dass dauernd hinter meinem Rücken getuschelt wird!"}]'::jsonb, 'mit wos a Gfrett haum'),
  ('si-umanaundgfrettn', 'si umanaundgfrettn', '', '', '', 'Grundwortschatz Wienerisch', 'sich rumgefretten', '[{"kategorie": "wörtlich", "text": "\"sich herumplagen\" (Kompositum aus dem abtrennbaren Präfix [[umanaund]]=\"herum\" und [[schurlen]]=\"plagen\")"}, {"kategorie": "allg.", "text": "sich abmühen, sich rumärgern, sich mit etwas herumschlagen"}]'::jsonb, 'I wüü mi mit dem Schaas nimma umanaundgfrettn miassn!'),
  ('i-wueue-mi-mit-dem-schaas-nimma-umanaundgfrettn-miassn', 'I wüü mi mit dem Schaas nimma umanaundgfrettn miassn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich möchte mich mit diesem Schas nicht mehr rumgfretten müssen!', '[{"kategorie": "wörtlich", "text": "\"Ich möchte mich mit diesem Dreckszeug nicht länger rumärgern!\"  2. Ich will mich mit diesem Mist nicht mehr weiter herumplagen müssen!  3. Ich habe keine Lust mehr, mich mit diesem Problem noch länger herumzuschlagen!"}]'::jsonb, 'si umanaundgfrettn'),
  ('si-gfrettn', 'si gfrettn', '', '', '', 'Grundwortschatz Wienerisch', 'sich gfretten', '[{"kategorie": "wörtlich", "text": "\"sich gefretten\" (vom mittelhochdeutschen \"vretten\"=\"plagen\")"}, {"kategorie": "allg.", "text": "sich mühen, sich plagen, sich schinden, sich quälen, sich aufreiben"}, {"kategorie": "fig.", "text": "sich grämen, sich Sorgen machen, sich den Kopf zerbrechen, sich verrückt machen"}]'::jsonb, 'Waunnst di toogaus toogei nua gfrettn muassd, valiasd iagendwaunn jeede Freid!'),
  ('waunnst-di-toogaus-toogei-nua-gfrettn-muassd-valiasd-iagendwaunn-jeede-freid', 'Waunnst di toogaus toogei nua gfrettn muassd, valiasd iagendwaunn jeede Freid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du dich tagaus tagein nur gfretten musst, verlierst du irgendwann jede Freude!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dich Tag für Tag nur quälen musst, verlierst du irgendwann die Lebensfreude!\"  2. Wenn du dich dauerhaft nur abmühst, geht dir irgendwann die Freude am Leben verloren!  3. Wenn du dich Tag für Tag nur aufreibst, bleibt irgendwann nichts mehr von dir übrig!"}]'::jsonb, 'si gfrettn'),
  ('si-ogfrettn', 'si ogfrettn', '', '', '', 'Grundwortschatz Wienerisch', 'sich abgfretten', '[{"kategorie": "wörtlich", "text": "\"sich abgefretten\" (eigtl. \"sich abgefretten\", vom mittelhochdeutschen \"vretten\"=\"plagen\")"}, {"kategorie": "allg.", "text": "sich abplagen, sich abmühen, sich abquälen, sich abrackern"}]'::jsonb, 'Wofia soi I mi ogfrettn, waunns ää oin wuaschd is?'),
  ('wofia-soi-i-mi-ogfrettn-waunns-aeae-oin-wuaschd-is', 'Wofia soi I mi ogfrettn, waunns ää oin wuaschd is?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wofür soll ich mich abgfretten, wenn''s eh allen wurscht ist?', '[{"kategorie": "wörtlich", "text": "\"Wofür soll ich mich abrackern, wenn''s eh allen egal ist?\"  2. Wofür soll ich mir den Buckel krumm arbeiten, wenn''s eh keinen interessiert?  3. Warum soll ich mich totarbeiten, wenn niemand meine Arbeit wertschätzt?"}]'::jsonb, 'si ogfrettn'),
  ('si-duachgfrettn', 'si duachgfrettn', '', '', '', 'Grundwortschatz Wienerisch', 'sich durchgfretten', '[{"kategorie": "wörtlich", "text": "\"sich mühsam durchquälen\" (eigtl. \"sich durchgefretten\", vom mittelhochdeutschen \"vretten\"=\"plagen\")"}, {"kategorie": "allg.", "text": "\"sich mühsam durchschlagen\", sich durchkämpfen, sich durchbeißen, sich durchboxen, sich durchlavieren"}]'::jsonb, 'Ma gfrett si duach im Leebm und froogd si ''wofia''?'),
  ('ma-gfrett-si-duach-im-leebm-und-froogd-si-wofia', 'Ma gfrett si duach im Leebm und froogd si ''wofia''?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Man gfrettet sich im Leben durch und fragt sich ''wofür''?', '[{"kategorie": "wörtlich", "text": "\"Man quält sich mühsam durchs Leben und fragt sich ''wofür''?\"  2. Man kämpft sich mühsam durchs Leben – und fragt sich irgendwann, wofür das alles gut sein soll!  3. Man schlägt sich mühsam durchs Leben – und die Frage nach dem Warum immer lauter!"}]'::jsonb, 'si duachgfrettn'),
  ('mit-gaudaeae-und-bahoeoe-foan-de-gschroppn-karussoeoe', 'Mit Gaudää und Bahöö foan de Gschroppn Karussöö!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit Gaudee und Bahöl fahr''n die Gschroppn Karussell!', '[{"kategorie": "wörtlich, Reim", "text": "\"\"Mit Gaudee und Bahöl fahr''n die Kinder Karussell!\"  2. Mit Freude und Riesenwirbel fahren die Kinder Karussel!  3. Mit [[Hetz]] und viel Geschrei fahren die Kinder [[Ringelspiel]]!  4. Mit Jubel und Trubel drehen die Kinder ihre Runden im Karussel!"}]'::jsonb, ''),
  ('ea-is-ollawaeu-auf-gaudaeae', 'Ea is ollawäu auf Gaudää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er ist alleweil auf Gaudee!', '[{"kategorie": "wörtlich", "text": "\"Er ist ständig auf Vergnügungstour!\"  2. Er ist ständig unterwegs, um Spaß zu haben!  3. Er ist im ständigen Ausgehfieber!  4. Er zieht ständig um die Häuser!"}]'::jsonb, ''),
  ('mia-gengan-auf-a-gaudaeae', 'Mia gengan auf a Gaudää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir gehen auf eine Gaudee!', '[{"kategorie": "wörtlich", "text": "\"Wir gehen auf Vergnügungstour!\"  2. Wir gehen aus, um Spaß zu haben!  3. Wir ziehen um die Häuser!"}]'::jsonb, ''),
  ('auf-gaudaeae-sei', 'auf Gaudää sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf Gaudee sein', '[{"kategorie": "wörtlich", "text": "\"auf Vergnügungstour sein\""}, {"kategorie": "", "text": "feuchtfröhlich unterwegs sein, um sich zu vergnügen"}, {"kategorie": "", "text": "sich einen [[Jux]] machen"}, {"kategorie": "", "text": "um die Häuser ziehen"}]'::jsonb, 'I kennt mei Leebm laung auf Gaudää sei!'),
  ('i-kennt-mei-leebm-laung-auf-gaudaeae-sei', 'I kennt mei Leebm laung auf Gaudää sei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich könnte mein Leben lang auf Gaudee sein!', '[{"kategorie": "wörtlich", "text": "\"Ich könnte mein ganzes Leben auf Vergnügungstour sein!\"  2. Ich könnte mein ganzes Leben allein dem Vergnügen widmen!  3. Ich könnte ein Leben lang um die Häuser ziehen!"}]'::jsonb, 'auf Gaudää sei'),
  ('nua-zwecks-gaudaeae', 'Nua zwecks Gaudää!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Nur zwecks Gaudee!', '[{"kategorie": "wörtlich", "text": "\"Bloß spaßhalber!\"  2. Nur zum Spaß!  3. Nur [[zwecks]] Theater!  4. Nur [[hetzhalber]]!"}]'::jsonb, ''),
  ('des-festl-gestan-woa-echd-gaudich', 'Des Festl gestan woa echd gaudich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Fest gestern war echt gaudig!', '[{"kategorie": "wörtlich", "text": "\"Die Feier gestern war echt amüsant!\"  2. Die Party gestern war echt unterhaltsam!  3. Die Party gestern war richtig spaßig!"}]'::jsonb, ''),
  ('des-is-a-gaudi', 'Des is a Gaudi!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist eine Gaudi!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Spaß!\"  2. Das ist ein Vergnügen!  3. Das ist eine [[Hetz]]!"}]'::jsonb, ''),
  ('waunnst-a-muadsgaudi-daleebm-wueuest-daunn-schmeiss-di-aufs-wiina-wiisnfest', 'Waunnst a Muadsgaudi daleebm wüüst, daunn schmeiss di aufs Wiina Wiisnfest!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wenn du eine Mordsgaudi erleben willst, dann schmeiß dich aufs Wiener Wiesenfest!', '[{"kategorie": "wörtlich", "text": "\"Wenn du einen Mordsspaß erleben willst, dann ab mit dir zum Wiener Wiesenfest!\"  2. Willst du mal so richtig abfeiern und die Sau rauslassen? Dann komm zum Wiener Wiesenfest!  3. Wenn du einmal ausgelassene Partystimmung ohne Ende live miterleben willst, dann darfst du das Wiener Wiesenfest nicht verpassen!"}]'::jsonb, 'a Muadsgaudi haum'),
  ('de-hittnparty-woara-botzngaudi-aum-schluss-haums-olle-auf-de-tisch-taunzd', 'De Hittnparty woara Botzngaudi - aum Schluss haums olle auf de Tisch taunzd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Hüttenparty war eine Batzengaudi - am Schluss haben sie alle auf den Tischen getanzt!', '[{"kategorie": "wörtlich", "text": "\"Die Hüttenparty war ein Riesenspaß – am Ende tanzten alle auf den Tischen!\"  2. Die Hüttenparty war ein Vergnügen  ohne Ende - zum Schluss wurde sogar auf den Tischen getanzt!  3. Die Hüttenparty war der Knaller - besonders die Table-Dance-Einlage am Schluss war ein echter Hammer!"}]'::jsonb, ''),
  ('si-hod-a-botznaungst-vua-schbinnan-waunn-de-ane-siichd-schbringts-aum-tisch', 'Si hod a Botznaungst vua Schbinnan - waunn de ane siichd, schbringts aum Tisch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie hat eine Batzenangst vor Spinnen – wenn sie eine sieht, springt sie auf den Tisch!', '[{"kategorie": "wörtlich", "text": "\"Sie hat eine Riesenangst vor Spinnen – wenn sie eine sieht, springt sie auf den Tisch!\"  2. Sie hat ’nen Riesenschiss vor Spinnen - wenn sie eine sieht, vollführt sie den Sprung aufs Mobiliar!  3. Sie hat eine Mordsangst vor Spinnen - kaum krabbelt was mit acht Beinen, hüpft sie auf den Tisch!"}]'::jsonb, ''),
  ('de-oide-hod-a-botznmaasl-ghobd-dass-da-zooi-ian-koffa-ned-kontrolliad-hod-waeu-sunst-sitzads-jetzt-im-landl', 'De Oide hod a Botznmaasl ghobd, dass da Zooi ian Koffa ned kontrolliad hod - wäu sunst sitzads jetzt im Landl!', '', '', '', 'Wiener Gaunersprache', 'Die Alte hat ein Batzenmasl gehabt, dass der Zoll ihren Koffer nicht kontrolliert hat - weil sonst würde sie jetzt im Landl einsitzen!', '[{"kategorie": "wörtlich", "text": "\"Die Alte hatte Riesenglück, dass der Zoll ihren Koffer nicht kontrolliert hat - weil sonst würde sie jetzt im Landesgericht für Strafsachen einsitzen!\"  2. Die Alte hat Riesenschwein gehabt, dass der Zoll nicht in ihren Koffer reingeschaut hat – sonst würde sie jetzt hinter schwedischen Gardinen sitzen!  3. So viel Glück wie die hat nicht mal der Papst beim Lotto – wär der Zöllner neugierig gewesen, wär sie längst weggesperrt!"}]'::jsonb, ''),
  ('i-hob-an-botznhunga-i-kenntad-an-gaunzn-oelefauntn-vadruckn', 'I hob an Botznhunga - I kenntad an gaunzn Ölefauntn vadruckn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich hab einen Batzenhunger - ich könnte einen ganzen Elefanten verdrücken!', '[{"kategorie": "wörtlich", "text": "\"Ich hab einen Mordshunger - ich könnte einen ganzen Elefanten verdrücken!\"  2. Ich hab riesigen Hunger - ich würd ’ne Kuh samt Stall fressen!  3. Ich hab Hunger wie ein Bauarbeiter - ich könnt ein ganzes Buffet leerfressen!"}]'::jsonb, ''),
  ('i-hob-an-botznduaschd-i-kennt-direkt-ausn-zopfhaun-saufn', 'I hob an Botznduaschd - I kennt direkt ausn Zopfhaun saufn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich habe einen Batzendurst - ich könnt'' direkt aus dem Zapfhahn saufen!', '[{"kategorie": "wörtlich", "text": "\"Ich habe einen Riesendurst - ich könnt'' direkt aus dem Zapfhahn saufen!\"  2. Ich hab so einen gewaltigen Durst, ich würd mir die Bierleitung am liebsten direkt in den Hals legen!  3. Ich hab so einen Mordsdurst, dass ich mich am liebsten mit offenem Mund unter’n Zapfhahn legen würd!"}]'::jsonb, ''),
  ('a-muadsdrumm-maasl', 'a muadsdrumm Maasl', '', '', '', 'Grundwortschatz Wienerisch', 'ein mordstrumm Masel', '[{"kategorie": "wörtlich", "text": "\"ein mordsmäßig großes Glück\""}, {"kategorie": "", "text": "ein [[Mordsglück]], Riesenglück, ein unglaublicher Segen, ein [[Botznmaasl]]"}]'::jsonb, 'De Oide hod a muadsdrumm Maasl ghobd, dass da Zooi ian Koffa ned kontrolliad hod - wäu sunst sitzads jetzt im Landl!'),
  ('de-oide-hod-a-muadsdrumm-maasl-ghobd-dass-da-zooi-ian-koffa-ned-kontrolliad-hod-waeu-sunst-sitzads-jetzt-im-landl', 'De Oide hod a muadsdrumm Maasl ghobd, dass da Zooi ian Koffa ned kontrolliad hod - wäu sunst sitzads jetzt im Landl!', '', '', '', 'Wiener Gaunersprache', 'Die Alte hat ein mordstrumm Masl gehabt, dass der Zoll ihren Koffer nicht kontrolliert hat - weil sonst würde sie jetzt im Landl einsitzen!', '[{"kategorie": "wörtlich", "text": "\"Die Alte hatte Riesenglück, dass der Zoll ihren Koffer nicht kontrolliert hat - weil sonst würde sie jetzt im Landesgericht für Strafsachen einsitzen!\"  2. Die Alte hat Riesenschwein gehabt, dass der Zoll nicht in ihren Koffer reingeschaut hat – sonst würde sie jetzt hinter schwedischen Gardinen sitzen!  3. So viel Glück wie die hat nicht mal der Papst beim Lotto – wär der Zöllner neugierig gewesen, wär sie längst weggesperrt!"}]'::jsonb, 'a muadsdrumm Maasl'),
  ('i-hob-an-woifshunga-i-kenntad-an-gaunzn-oelefauntn-vadruckn', 'I hob an Woifshunga - I kenntad an gaunzn Ölefauntn vadruckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hab einen Wolfshunger - ich könnte einen ganzen Elefanten verdrücken!', '[{"kategorie": "wörtlich", "text": "\"Ich hab einen Mordshunger - ich könnte einen ganzen Elefanten verdrücken!\"  2. Ich hab riesigen Hunger - ich würd ’ne Kuh samt Stall fressen!  3. Ich hab Hunger wie ein Bauarbeiter - ich könnt ein ganzes Buffet leerfressen!"}]'::jsonb, ''),
  ('i-hob-an-muadshunga-i-kenntad-an-gaunzn-oelefauntn-vadruckn', 'I hob an Muadshunga - I kenntad an gaunzn Ölefauntn vadruckn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich hab einen Mordshunger - ich könnte einen ganzen Elefanten verdrücken!', '[{"kategorie": "wörtlich", "text": "\"Ich hab einen Riesenhunger - ich könnte einen ganzen Elefanten verdrücken!\"  2. Ich hab gewaltigen Hunger - ich würd ’ne Kuh samt Stall fressen!  3. Ich hab Hunger wie ein Bauarbeiter - ich könnt ein ganzes Buffet leerfressen!"}]'::jsonb, ''),
  ('i-hob-an-moeadahunga-i-kenntad-an-gaunzn-oelefauntn-vadruckn', 'I hob an Möadahunga - I kenntad an gaunzn Ölefauntn vadruckn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich hab einen Mörderhunger - ich könnte einen ganzen Elefanten verdrücken!', '[{"kategorie": "wörtlich", "text": "\"Ich hab einen Riesenhunger - ich könnte einen ganzen Elefanten verdrücken!\"  2. Ich hab gewaltigen Hunger - ich würd ’ne Kuh samt Stall fressen!  3. Ich hab Hunger wie ein Bauarbeiter - ich könnt ein ganzes Buffet leerfressen!"}]'::jsonb, ''),
  ('i-hob-an-muadsduaschd-i-kennt-direkt-ausn-zopfhaun-saufn', 'I hob an Muadsduaschd - I kennt direkt ausn Zopfhaun saufn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich habe einen Mordsdurst - ich könnt'' direkt aus dem Zapfhahn saufen!', '[{"kategorie": "wörtlich", "text": "\"Ich habe einen Riesendurst - ich könnt'' direkt aus dem Zapfhahn saufen!\"  2. Ich hab so einen gewaltigen Durst, ich würd mir die Bierleitung am liebsten direkt in den Hals legen!  3. Ich hab so einen Batzendurst, dass ich mich am liebsten mit offenem Mund unter’n Zapfhahn legen würd!"}]'::jsonb, ''),
  ('da-tommi-hoda-muadsglick-dass-sei-oide-so-schaasaugad-is-sunst-warada-laengst-wiida-solo', 'Da Tommi hoda Muadsglick, dass sei Oide so schaasaugad is - sunst warada längst wiida solo!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Tommy hat ein Mordsglück, dass seine Alte so schasaugert ist – sonst wär er längst wieder solo!', '[{"kategorie": "wörtlich", "text": "\"Der Tommy hat Riesenglück, dass seine Alte so schlecht sieht – sonst wär er längst wieder solo!\"  2. Der Tommy hat Schweineglück, dass seine Alte fast blind ist – sonst hätt sie ihn wegen seiner neuen Flamme schon längst stehengelassen!  3. Der Tommy hat hat ''nen Riesendusel, dass seine Alte so schlecht sieht - sonst hätt sie ihn samt seiner neuen Flamme schon längst ertappt!"}]'::jsonb, ''),
  ('des-daeataschdickl-woara-muadsvagnueueng-soeoetn-so-glochd', 'Des Däataschdickl woara Muadsvagnüüng - söötn so glochd!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Das Theaterstück war ein Mordsvergnügen – selten so gelacht!', '[{"kategorie": "wörtlich", "text": "\"Das Theaterstück war ein rauschendes Vergnügen – ich habe selten so herzhaft gelacht!\"  2. Das Theaterstück war ein Riesenspaß - Lachen ohne Ende!  3. Die Theatervorstellung war der absolute Brüller - ich bin aus dem Lachen gar nicht mehr rausgekommen!"}]'::jsonb, ''),
  ('de-gerichdsvahaundlung-woara-muadsuntahoidung-de-kaschbaln-auf-da-richtabaunk-haum-mi-im-zweifae-sogoa-freigschbrochn', 'De Gerichdsvahaundlung woara Muadsuntahoidung - de Kaschbaln auf da Richtabaunk haum mi im Zweifä sogoa freigschbrochn!', '', '', '', 'Wiener Gaunersprache', 'Die Gerichtsverhandlung war eine Mordsunterhaltung - die Kasperln auf der Richterbank haben mich im Zweifel sogar freigesprochen!', '[{"kategorie": "wörtlich", "text": "\"Die Gerichtsverhandlung war eine Mordsgaudi - die Kasperln auf der Richterbank haben mich im Zweifel sogar freigesprochen!\"  2. Die Verhandlung war ’ne bessere Sketchshow – und am Schluss hab ich von den Clowns auf der Richterbank sogar einen Freifahrtschein bekommen!  3. Die Gerichtsverhandlung war ''ne echte Show - Richter wie Clowns, das Urteil ein Glückslos, kurzum: Mordsunterhaltung mit Happy End!"}]'::jsonb, ''),
  ('wia-haum-an-muadskoarl-ghobd-und-wueuede-saufliada-brueued-bis-de-hee-kumma-is', 'Wia haum an Muadskoarl ghobd und wüüde Saufliada brüüd - bis de Hee kumma is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wir haben einen Mordskarl gehabt und wilde Sauflieder gebrüllt - bis die Höh gekommen ist!', '[{"kategorie": "wörtlich", "text": "\"Wir haben einen Mordsspaß gehabt und wilde Sauflieder gebrüllt - bis die Polizei gekommen ist!\"  2. Wir hatten eine Mordsgaudi und haben das ganze Wirtshaus zusammengeschrien – bis die Blaulichter vorm Fenster blinkten!  3. Wir hatten eine Riesenhetz mit Saufmusik, Gesang und Gebrüll – bis die Bullen an der Tür geklopft haben!"}]'::jsonb, ''),
